head.b:skin:
:root{--green:#173D2D;--green-dark:#102a20;--mango:#F4B942;--cream:#FFF8EB;--brown:#302019;--white:#fff;--muted:#756B5F;--container:1320px;--nav:82px}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--cream);color:var(--brown);font:16px/1.6 'DM Sans',sans-serif;overflow-x:hidden}body.locked{overflow:hidden}img{display:block;max-width:100%}a{color:inherit;text-decoration:none}button,input{font:inherit}button{cursor:pointer}button,a{touch-action:manipulation}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid var(--mango);outline-offset:3px}section{scroll-margin-top:var(--nav)}.container{width:min(var(--container),calc(100% - 10%));margin-inline:auto}.section{padding:clamp(85px,9vw,145px) 0}h1,h2,h3,p{margin:0}h1,h2,h3{font-family:'Playfair Display',Georgia,serif;font-weight:400;line-height:1.05;letter-spacing:-.045em}h2{font-size:clamp(3rem,5.7vw,5.8rem)}em{font-weight:400}.eyebrow{color:var(--mango);font-size:.68rem;letter-spacing:.18em;font-weight:700;display:flex;align-items:center;gap:12px}.eyebrow:before{content:'';width:28px;height:1px;background:currentColor}.dark-eyebrow{color:#906019}.button{display:inline-flex;align-items:center;justify-content:center;gap:28px;min-height:52px;border:1px solid var(--mango);border-radius:4px;background:var(--mango);color:var(--green-dark);padding:12px 24px;font-size:.78rem;font-weight:700;transition:transform .25s,background .25s}.button:hover{transform:translateY(-3px);background:#ffcc66}.button-outline{background:transparent;border-color:rgba(255,248,235,.55);color:var(--white)}.button-outline:hover{background:var(--cream);color:var(--green)}.button-small{min-height:43px;padding:9px 18px}.text-link{display:inline-flex;gap:25px;border-bottom:1px solid var(--green);padding-bottom:9px;font-size:.7rem;font-weight:700;letter-spacing:.12em}.skip{position:fixed;z-index:200;top:-100px;left:10px;background:var(--mango);padding:10px}.skip:focus{top:10px}.header{position:fixed;z-index:40;top:0;left:0;right:0;height:var(--nav);color:var(--white);border-bottom:1px solid rgba(255,255,255,.18);transition:background .3s}.header.scrolled,.header.open{background:rgba(16,42,32,.97)}.nav{height:100%;display:flex;align-items:center;justify-content:space-between;gap:20px}.logo{display:flex;align-items:center;gap:9px;font-family:Georgia,serif;font-size:1rem;font-weight:bold;letter-spacing:.06em;line-height:1;white-space:nowrap}.logo-symbol{color:var(--mango);font-size:2.3rem;line-height:1}.logo small{display:block;font:600 .49rem 'DM Sans',sans-serif;letter-spacing:.27em;margin-top:6px}.nav-links{display:flex;align-items:center;gap:clamp(14px,2vw,30px);font-size:.76rem}.nav-links a{opacity:.85}.nav-links a:hover{opacity:1;color:var(--mango)}.nav-actions{display:flex;align-items:center;gap:12px}.bag-button{color:var(--white);background:none;border:0;padding:10px;font-size:.76rem;white-space:nowrap}.bag-button span{color:var(--mango);margin-left:4px}.nav-toggle,.mobile-order{display:none}.hero{position:relative;min-height:720px;min-height:100svh;color:var(--white);background:var(--green-dark);overflow:hidden}.hero-photo,.hero-shade,.ambience-photo,.ambience-overlay{position:absolute;inset:0;pointer-events:none}.hero-photo{background:linear-gradient(90deg,rgba(13,38,28,.94),rgba(13,38,28,.82) 52%,rgba(13,38,28,.42)),url('https://images.unsplash.com/photo-1552566626-52f8b828add9?auto=format&fit=crop&w=1800&q=75') center/cover}.hero-shade{background:linear-gradient(0deg,rgba(10,31,23,.8),transparent 45%)}.hero-layout{position:relative;z-index:1;min-height:720px;min-height:100svh;display:grid;grid-template-columns:1fr 1fr;align-items:center;gap:3%;padding-top:110px;padding-bottom:100px}.hero-copy{max-width:650px}.hero h1{font-size:clamp(4.2rem,7.6vw,8.2rem);margin:28px 0 25px}.hero h1 em,.signature h2 em,.ambience h2 em,.visit h2 em{color:var(--mango)}.hero-copy p{max-width:430px;color:#e5e7d9;font-size:1rem}.hero-buttons{display:flex;flex-wrap:wrap;gap:12px;margin-top:34px}.hero-art{position:relative;width:min(100%,565px);justify-self:end}.hero-art-frame{aspect-ratio:1;overflow:hidden;border-radius:50%;border:1px solid rgba(244,185,66,.7);padding:12px;box-shadow:0 0 100px rgba(244,185,66,.14)}.hero-art-frame img{width:100%;height:100%;object-fit:cover;border-radius:50%}.hero-stamp{position:absolute;right:-10px;bottom:12%;width:110px;height:110px;border-radius:50%;background:var(--mango);color:var(--green);display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;font-size:.55rem;letter-spacing:.1em;line-height:1.5;transform:rotate(12deg)}.hero-stamp strong{font:italic 1.15rem Georgia,serif;letter-spacing:0}.art-caption{display:block;text-align:center;font-size:.57rem;letter-spacing:.2em;margin-top:20px;color:#e9d3a2}.hero-bottom{position:absolute;z-index:2;bottom:27px;left:0;right:0;display:flex;justify-content:space-between;font-size:.58rem;letter-spacing:.16em;color:#d6dfcf}.scroll-icon{display:inline-flex;border:1px solid #ced7c4;border-radius:30px;width:25px;height:34px;align-items:center;justify-content:center;margin-right:9px}.hero-orb{position:absolute;border-radius:50%;background:var(--mango);opacity:.45;pointer-events:none;animation:float 5s ease-in-out infinite}.orb-one{width:6px;height:6px;top:25%;left:52%}.orb-two{width:4px;height:4px;top:68%;left:46%;animation-delay:-2s}@keyframes float{50%{transform:translateY(-20px);opacity:.8}}.story{background:var(--cream)}.story-grid{display:grid;grid-template-columns:1fr 1fr;gap:10%;align-items:center}.story-visual{position:relative;min-height:600px}.story-img{overflow:hidden;position:absolute}.story-img img{width:100%;height:100%;object-fit:cover}.story-img-main{left:0;top:0;width:73%;height:88%;border-radius:180px 180px 4px 4px}.story-img-small{right:0;bottom:0;width:45%;height:47%;border:10px solid var(--cream);border-radius:150px 150px 4px 4px}.story-note{position:absolute;left:5%;bottom:0;background:var(--green);color:var(--cream);width:145px;padding:18px;font-size:.65rem;letter-spacing:.1em;line-height:1.5}.story-note span{color:var(--mango);font-size:1.5rem}.story-note em{font:italic 1.5rem Georgia,serif;letter-spacing:0;color:var(--mango)}.story-copy h2,.section-top h2{margin:20px 0 24px;color:var(--green)}.story-copy h2 em,.section-top h2 em{color:#b67824}.story-copy p{max-width:490px;color:var(--muted);margin-bottom:18px}.story-copy .text-link{margin-top:15px}.story-stats{display:flex;gap:clamp(20px,4vw,55px);border-top:1px solid #d9ceba;margin-top:50px;padding-top:25px}.story-stats strong{display:block;font:1.7rem Georgia,serif;color:#b67824}.story-stats span{font-size:.56rem;letter-spacing:.12em;font-weight:700}.signature{background:var(--green-dark);color:var(--cream);overflow:hidden}.signature-layout{display:grid;grid-template-columns:.85fr 1.15fr;align-items:center;gap:5%;position:relative}.signature-copy h2{margin:22px 0}.signature-copy p{max-width:420px;color:#c8d2c4;margin-bottom:26px}.signature-copy .fine-print{margin-top:25px;font-size:.68rem}.signature-scene{min-height:560px;position:relative;display:flex;align-items:center;justify-content:center}.signature-scene img{position:relative;width:min(75%,465px);aspect-ratio:1;object-fit:cover;border-radius:50%;box-shadow:0 30px 80px #0007}.signature-ring{position:absolute;width:85%;max-width:560px;aspect-ratio:1;border:1px solid rgba(244,185,66,.3);border-radius:50%}.ingredient{position:absolute;z-index:2;font-size:.68rem;letter-spacing:.08em;background:var(--green-dark);padding:8px 10px;color:var(--mango)}.ingredient small{display:block;letter-spacing:0;color:#d2dbc9;font-size:.68rem}.ingredient:before{content:'';position:absolute;width:42px;height:1px;background:var(--mango);top:50%;right:100%}.ingredient-one{right:1%;top:20%}.ingredient-two{left:0;top:48%}.ingredient-two:before{left:100%}.ingredient-three{right:3%;bottom:18%}.signature-side{position:absolute;right:-3%;writing-mode:vertical-rl;letter-spacing:.2em;font-size:.6rem;color:#90a899}.menu-section{background:#f7efdf}.section-top{display:flex;align-items:end;justify-content:space-between;gap:40px}.section-top h2{margin-bottom:0}.section-top>div:last-child,.section-top>p{max-width:340px;color:var(--muted);font-size:.9rem}.demo-label{display:inline-block;color:#8b602d;font-size:.6rem;letter-spacing:.12em;font-weight:700;margin-top:14px}.menu-tools{display:flex;align-items:center;gap:20px;margin-top:45px;border-bottom:1px solid #d9cfbd}.filter-scroll{display:flex;gap:8px;overflow-x:auto;scrollbar-width:thin;flex:1;min-width:0;padding-bottom:14px}.filter{white-space:nowrap;background:transparent;color:#766a5b;border:1px solid transparent;border-radius:30px;padding:9px 16px;font-size:.75rem}.filter.active{background:var(--green);color:var(--cream)}.carousel-arrows{display:flex;gap:8px;padding-bottom:14px}.circle-button,.close-button{width:46px;height:46px;border:1px solid #b9ad9d;border-radius:50%;background:transparent;color:var(--green);font-size:1.2rem;flex:none}.circle-button:hover{background:var(--green);color:white}.swipe-hint{font-size:.6rem;letter-spacing:.17em;color:#867d70;margin:22px 0 12px}.swipe-hint span{font-size:1.1rem;color:var(--green)}.carousel{display:flex;overflow-x:auto;gap:20px;scroll-snap-type:x mandatory;scrollbar-width:thin;scrollbar-color:#b8a786 transparent;padding:10px 0 24px;overscroll-behavior-x:contain}.food-card{scroll-snap-align:center;flex:0 0 calc((100% - 60px)/4);min-width:0;background:var(--cream);border:1px solid #e6dac5;border-radius:8px;overflow:hidden;transition:transform .35s,box-shadow .35s}.food-card.active{transform:translateY(-7px);box-shadow:0 20px 35px rgba(48,32,25,.12)}.food-card img{width:100%;aspect-ratio:1/1;object-fit:cover;background:#e8dfd0}.food-card-content{padding:20px}.food-card .card-category{font-size:.6rem;color:#9b6b28;letter-spacing:.13em;text-transform:uppercase}.food-card h3{font-size:1.6rem;margin:9px 0}.food-card p{font-size:.78rem;color:var(--muted);min-height:3.2em}.food-card .card-price{display:block;color:var(--green);font:1.25rem Georgia,serif;margin:15px 0 4px}.availability{font-size:.65rem;color:#6c7463}.card-actions{display:flex;gap:8px;margin-top:15px}.card-actions button{flex:1;min-height:42px;border:1px solid var(--green);background:transparent;color:var(--green);font-size:.7rem;font-weight:700;padding:8px}.card-actions button:last-child{background:var(--green);color:white}.card-actions button:disabled{opacity:.45;cursor:not-allowed}.carousel-status,.menu-disclaimer{font-size:.7rem;color:var(--muted);margin-top:8px}.gallery-section{background:var(--cream)}.gallery-note{font-size:.7rem;color:var(--muted);margin:20px 0 25px}.gallery-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:14px}.gallery-grid figure{margin:0;overflow:hidden;border-radius:8px;position:relative;background:#e5dbca}.gallery-grid img{width:100%;aspect-ratio:4/5;object-fit:cover;transition:transform .5s}.gallery-grid figure:hover img{transform:scale(1.05)}.gallery-grid figcaption{position:absolute;bottom:0;left:0;right:0;padding:30px 12px 12px;color:white;font-size:.72rem;background:linear-gradient(transparent,rgba(0,0,0,.68))}.ambience{position:relative;min-height:660px;display:flex;align-items:center;overflow:hidden;background:var(--green);color:white}.ambience-photo{background:url('https://images.unsplash.com/photo-1445116572660-236099ec97a0?auto=format&fit=crop&w=1800&q=80') center/cover}.ambience-overlay{background:linear-gradient(90deg,rgba(9,32,23,.93),rgba(9,32,23,.6) 50%,rgba(9,32,23,.15))}.ambience-content{position:relative;padding:100px 0}.ambience h2{margin:24px 0}.ambience p{max-width:430px;color:#e1e5d8;margin-bottom:30px}.image-credit{display:block;font-size:.65rem;color:#d2dbca;margin-top:25px}.visit{background:var(--green);color:var(--cream)}.visit-grid{display:grid;grid-template-columns:1.2fr .8fr;align-items:center;gap:10%}.visit h2{margin:25px 0}.visit-copy>p{max-width:420px;color:#cdd8c9}.visit-buttons{display:flex;flex-wrap:wrap;gap:10px;margin-top:35px}.visit-card{border:1px solid rgba(244,185,66,.4);padding:clamp(25px,4vw,45px);position:relative}.card-star{position:absolute;top:20px;right:28px;color:var(--mango);font-size:2rem}.visit-card h3{font-size:2.5rem;margin:20px 0 30px}.visit-line{padding:15px 0;border-top:1px solid #547062;display:grid;grid-template-columns:90px 1fr;gap:10px}.visit-line span{color:var(--mango);font-size:.6rem;letter-spacing:.13em}.visit-line strong{font-size:.8rem;font-weight:400}.social-links{display:flex;gap:15px;flex-wrap:wrap}.social-links a{font-size:.75rem;text-decoration:underline}.light-link{border-color:var(--mango);color:var(--mango);margin-top:25px}.footer{background:#0c241a;color:#ccd6c8;padding:70px 0 25px}.footer-main{display:grid;grid-template-columns:2fr 1fr 1fr 1.5fr;gap:30px}.footer .logo{color:white}.footer p{font-size:.8rem;margin-top:20px}.footer-main>div:not(:first-child){display:flex;flex-direction:column;gap:9px}.footer-main strong{font-size:.65rem;letter-spacing:.14em;color:var(--mango);margin-bottom:8px}.footer-main a:not(.logo){font-size:.8rem}.footer-message{font:1.5rem Georgia,serif;color:white}.footer-message em{color:var(--mango)}.footer-bottom{border-top:1px solid #355145;margin-top:60px;padding-top:22px;display:flex;justify-content:space-between;gap:15px;font-size:.58rem;letter-spacing:.12em}.overlay{position:fixed;z-index:60;inset:0;background:rgba(0,0,0,.7)}.hidden,[hidden]{display:none!important}.drawer{position:fixed;z-index:61;top:0;bottom:0;right:0;width:min(440px,100%);background:var(--cream);padding:28px;overflow-y:auto}.drawer-head{display:flex;align-items:start;justify-content:space-between}.drawer-head h2{font-size:2.8rem;color:var(--green);margin:15px 0}.drawer-note,.fine-print{font-size:.72rem;color:var(--muted)}.cart-item{border-bottom:1px solid #ded3c0;padding:20px 0}.cart-item strong{display:block}.cart-item small{color:var(--muted)}.cart-row{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-top:10px}.cart-row input{width:60px;padding:7px;border:1px solid #c8bba7;background:white}.cart-row button{border:0;background:none;text-decoration:underline;color:var(--green)}.cart-total{display:flex;justify-content:space-between;padding:25px 0}.cart-checkout{width:100%}.modal{position:fixed;z-index:61;top:50%;left:50%;transform:translate(-50%,-50%);width:min(880px,calc(100% - 32px));max-height:calc(100dvh - 32px);overflow-y:auto;background:var(--cream);display:grid;grid-template-columns:1fr 1fr;box-shadow:0 20px 70px #0008}.modal-close{position:absolute;right:15px;top:15px;z-index:2;background:var(--cream)}.detail-image img{width:100%;height:100%;min-height:450px;object-fit:cover}.detail-content{padding:50px 35px}.detail-content h2{font-size:clamp(2.5rem,4vw,4rem);color:var(--green);margin:16px 0}.detail-content p{font-size:.85rem;color:var(--muted);margin:12px 0}.detail-price{font:1.5rem Georgia,serif;color:#b67824}.detail-content label{display:block;font-size:.75rem;margin-top:20px}.detail-content input{display:block;width:80px;padding:10px;margin:8px 0 18px;border:1px solid #b9ad9d;background:white}.detail-message{min-height:1em}.back-menu{border:0;background:none;color:var(--green);padding:10px 0;text-decoration:underline}.blog-area{padding:130px 5% 70px;max-width:1100px;margin:auto}.blog-area img{max-width:100%;height:auto}.blog-area a{color:var(--green)}
@media(max-width:1050px){.nav-links{gap:14px}.nav-order{display:none}.food-card{flex-basis:calc((100% - 40px)/3)}.gallery-grid{grid-template-columns:repeat(3,1fr)}}
@media(max-width:800px){:root{--nav:72px}.nav{gap:8px}.logo{font-size:.82rem}.logo-symbol{font-size:1.8rem}.logo small{font-size:.43rem}.nav-links{display:none;position:absolute;top:72px;left:0;right:0;background:var(--green-dark);padding:12px 5% 25px;max-height:calc(100dvh - 72px);overflow-y:auto;flex-direction:column;align-items:stretch;gap:0;border-bottom:1px solid #4a6657}.header.open .nav-links{display:flex}.nav-links a{padding:12px 0;font-size:.9rem}.nav-links .mobile-order{display:block;color:var(--mango);font-weight:700}.nav-toggle{display:flex;flex-direction:column;justify-content:center;gap:5px;width:44px;height:44px;border:1px solid #789184;border-radius:50%;background:none;padding:11px}.nav-toggle span{height:1px;width:100%;background:white}.nav-actions{gap:4px}.hero-layout{grid-template-columns:1fr 1fr}.hero h1{font-size:clamp(3.5rem,8vw,5.5rem)}.story-grid,.signature-layout,.visit-grid{grid-template-columns:1fr;gap:50px}.story-visual{min-height:520px;max-width:600px;width:100%;order:2}.signature-scene{min-height:480px}.signature-side{display:none}.visit-grid{gap:45px}.footer-main{grid-template-columns:1fr 1fr}.footer-message{grid-column:1/-1}.section-top{align-items:start;flex-direction:column;gap:20px}.gallery-grid{grid-template-columns:repeat(3,1fr)}}
@media(max-width:600px){.container{width:calc(100% - 36px)}.section{padding:75px 0}.hero-layout{display:flex;flex-direction:column;align-items:stretch;justify-content:center;min-height:0;padding-top:120px;padding-bottom:110px;gap:35px}.hero{min-height:100svh}.hero h1{font-size:clamp(3.35rem,13vw,5rem);margin:20px 0}.hero-copy p{font-size:.9rem}.hero-art{width:min(72%,300px);align-self:center}.hero-stamp{width:80px;height:80px;font-size:.45rem}.hero-stamp strong{font-size:.85rem}.art-caption{font-size:.5rem}.hero-bottom{bottom:20px}.hero-bottom>span{display:none}.story-visual{min-height:400px}.story-stats{gap:15px;justify-content:space-between}.story-stats span{font-size:.5rem}.signature-scene{min-height:360px}.signature-scene img{width:75%}.ingredient{font-size:.56rem}.ingredient small{font-size:.57rem}.ingredient:before{width:20px}.section-top h2,h2{font-size:clamp(2.8rem,11vw,4rem)}.menu-tools{gap:10px;margin-top:30px}.carousel-arrows{gap:4px}.circle-button{width:40px;height:40px}.food-card{flex-basis:84%;scroll-snap-align:start}.food-card.active{transform:none}.food-card img{aspect-ratio:4/3}.gallery-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.ambience{min-height:580px}.ambience-content{padding:90px 0}.visit-buttons{align-items:stretch}.visit-buttons .button{flex:1 1 140px}.footer-main{gap:35px 20px}.footer-bottom{flex-direction:column}.modal{display:block}.detail-image img{height:220px;min-height:0}.detail-content{padding:25px}.drawer{padding:22px}.cart-row{flex-wrap:wrap}}
@media(max-width:340px){.logo{font-size:.73rem}.logo-symbol{font-size:1.5rem}.bag-button{padding:5px}.hero h1{font-size:3.15rem}.hero-buttons .button{flex:1 1 auto}.gallery-grid{grid-template-columns:1fr 1fr}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*:before,*:after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}}

/* Dedicated menu and dish routes, designed for narrow screens first. */
.header .nav {padding-left:env(safe-area-inset-left);padding-right:env(safe-area-inset-right)}
body.inner-view .header{background:var(--green-dark)}
button:disabled{cursor:not-allowed;opacity:.55}.whatsapp-status{font-size:.75rem;color:#f7e3ac;margin-top:12px;min-height:1.2em}.hero-buttons button{font:inherit;font-size:.78rem;font-weight:700}.hero-copy .whatsapp-status{color:#fff1cb}
.view-page{min-height:70vh;padding:calc(var(--nav) + 55px) 0 85px;background:var(--cream)}.view-page h1{font-size:clamp(3rem,7vw,6.5rem);color:var(--green);margin:20px 0}.view-page h1 em,.view-page h2 em{color:#b67824}.view-lead{max-width:650px;color:var(--muted)}.view-tools{margin:30px 0 20px;display:flex;gap:12px;flex-wrap:wrap;align-items:end}.view-search{display:grid;gap:5px;max-width:350px;width:100%;font-size:.75rem}.view-search input,.dish-fields input,.dish-fields textarea{min-height:48px;width:100%;border:1px solid #b9ad9d;border-radius:4px;background:white;color:var(--brown);padding:11px}.view-filters{display:flex;gap:8px;overflow-x:auto;padding:10px 0 18px;scrollbar-width:thin}.view-filters .filter{border-color:#e3d6c1;min-height:44px}.complete-grid{display:grid;grid-template-columns:1fr;gap:16px}.complete-grid .food-card{transform:none;box-shadow:none}.complete-grid .food-card img{aspect-ratio:4/3}.complete-grid .food-card p{min-height:0}.complete-grid .food-card-content{padding:17px}.full-menu-actions{margin-top:30px;display:flex;gap:15px;align-items:center;flex-wrap:wrap}.full-menu-actions .whatsapp-status{color:#765521;margin:0}
.dish-layout{display:grid;gap:28px}.dish-photo{width:100%;aspect-ratio:4/3;object-fit:cover;border-radius:12px;background:#e8dfd0}.dish-copy h1{font-size:clamp(2.8rem,6vw,5rem);margin:15px 0}.dish-copy p{color:var(--muted);margin:14px 0}.dish-price{color:var(--green);font:1.65rem Georgia,serif}.dish-fields{display:grid;gap:12px;margin:25px 0}.dish-fields label{display:grid;gap:6px;font-size:.78rem;font-weight:700}.dish-fields input[type=number]{max-width:100px}.dish-fields textarea{resize:vertical;min-height:80px}.dish-actions{display:flex;flex-wrap:wrap;gap:10px}.dish-actions .button{flex:1 1 180px}.dish-actions .button-outline{color:var(--green);border-color:var(--green)}.dish-actions .button-outline:hover{background:var(--green);color:white}.related{margin-top:70px}.related h2{color:var(--green);font-size:clamp(2.3rem,4vw,3.6rem);margin-bottom:20px}.related-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.related-card{min-width:0;background:#f6eddd;border:1px solid #e7d9c3;border-radius:8px;overflow:hidden}.related-card img{width:100%;aspect-ratio:4/3;object-fit:cover}.related-card a{display:block;padding:12px;font-weight:700;font-size:.85rem;min-height:48px;color:var(--green)}.back-link{display:inline-block;padding:12px 0;color:var(--green);font-size:.8rem;font-weight:700}.sample-reviews{background:#f7efdf}.review-list{display:grid;gap:14px;margin-top:35px}.review-card{background:var(--cream);padding:25px;border:1px solid #e4d6bf;border-radius:8px}.review-card blockquote{font:1.25rem/1.45 Georgia,serif;margin:0 0 16px;color:var(--green)}.review-card small{color:var(--muted)}.review-note{color:var(--muted);font-size:.75rem;margin-top:15px}.food-card .card-actions button{min-height:48px}.filter,.cart-row button{min-height:44px}.nav-links a{min-height:44px;display:flex;align-items:center}.footer a:not(.logo){min-height:44px;display:flex;align-items:center}.skip{color:#102a20}.header .nav-toggle{flex:none}
@media(min-width:520px){.complete-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.review-list{grid-template-columns:repeat(3,1fr)}}
@media(min-width:900px){.complete-grid{grid-template-columns:repeat(4,minmax(0,1fr))}.dish-layout{grid-template-columns:1fr 1fr;gap:6%;align-items:start}.dish-photo{aspect-ratio:1}.related-grid{grid-template-columns:repeat(4,1fr)}}
@media(max-width:600px){.hero-layout{padding-top:calc(100px + env(safe-area-inset-top));padding-bottom:90px}.view-page{padding-top:calc(var(--nav) + 35px)}.hero-buttons .button{min-height:48px}.gallery-grid figcaption{font-size:.76rem}.food-card p{font-size:.85rem}.bag-button{min-height:44px}.footer-bottom{padding-bottom:env(safe-area-inset-bottom)}}

body.script:
/* THE MANGO TREE CAFE CONFIGURATION
   Replace the demo menu, prices and image URLs with verified, licensed cafe content.
   Prices are in INR and illustrative only; do not use client-side totals for payment.
   whatsapp must contain country code and digits only (e.g. 91...), or remain empty.
   mapsUrl may point to the exact cafe location once verified. Never put secrets here. */
const CONFIG = {
  currency: '₹', address: '', hours: '', phone: '', email: '', whatsapp: '', mapsUrl: '',
  instagram: '', facebook: '',
  images: {
    hero:'https://images.unsplash.com/photo-1568901346375-23c9450c58cd?auto=format&fit=crop&w=1000&q=80',
    heroBackground:'https://images.unsplash.com/photo-1552566626-52f8b828add9?auto=format&fit=crop&w=1800&q=75',
    ambience:'https://images.unsplash.com/photo-1445116572660-236099ec97a0?auto=format&fit=crop&w=1800&q=80',
    story:'https://images.unsplash.com/photo-1552566626-52f8b828add9?auto=format&fit=crop&w=900&q=80',
    storyFood:'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=600&q=80',
    signature:'https://images.unsplash.com/photo-1568901346375-23c9450c58cd?auto=format&fit=crop&w=1000&q=80'
  },
  signatureLabels:[{title:'THE BUN',detail:'Golden & soft'},{title:'THE FILLING',detail:'Layered with flavor'},{title:'THE FINISH',detail:'Made for sharing'}],
  categories:['Pizza','Burgers','Pasta','Noodles','Momos','Sandwiches','Snacks','Main Course','Desserts','Cakes','Coffee & Tea','Shakes & Beverages'],
  products:[
    {id:'pizza',name:'Garden Pizza',category:'Pizza',price:299,description:'A colorful, cheesy slice for sharing.',ingredients:'',diet:'',available:true,image:'https://images.unsplash.com/photo-1513104890138-7c749659a591?auto=format&fit=crop&w=800&q=80'},
    {id:'burger',name:'Loaded Burger',category:'Burgers',price:220,description:'A satisfying stack of flavor in a golden bun.',ingredients:'',diet:'',available:true,image:'https://images.unsplash.com/photo-1568901346375-23c9450c58cd?auto=format&fit=crop&w=800&q=80'},
    {id:'pasta',name:'Creamy Pasta',category:'Pasta',price:260,description:'Comforting pasta with a deliciously creamy finish.',ingredients:'',diet:'',available:true,image:'https://images.unsplash.com/photo-1473093295043-cdd812d0e601?auto=format&fit=crop&w=800&q=80'},
    {id:'noodles',name:'Cafe Noodles',category:'Noodles',price:210,description:'A savory bowl for a comforting bite.',ingredients:'',diet:'',available:true,image:'https://images.unsplash.com/photo-1569718212165-3a8278d5f624?auto=format&fit=crop&w=800&q=80'},
    {id:'momos',name:'Steamed Momos',category:'Momos',price:180,description:'Little parcels made for sharing and dipping.',ingredients:'',diet:'',available:true,image:'https://images.unsplash.com/photo-1563245372-f21724e3856d?auto=format&fit=crop&w=800&q=80'},
    {id:'sandwich',name:'Cafe Sandwich',category:'Sandwiches',price:190,description:'A hearty favorite for any time of day.',ingredients:'',diet:'',available:true,image:'https://images.unsplash.com/photo-1528735602780-2552fd46c7af?auto=format&fit=crop&w=800&q=80'},
    {id:'fries',name:'Golden Fries',category:'Snacks',price:140,description:'Golden, crispy, and made for the table.',ingredients:'',diet:'',available:true,image:'https://images.unsplash.com/photo-1573080496219-bb080dd4f877?auto=format&fit=crop&w=800&q=80'},
    {id:'main',name:'Comfort Bowl',category:'Main Course',price:280,description:'A satisfying bowl for a bigger appetite.',ingredients:'',diet:'',available:true,image:'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=800&q=80'},
    {id:'dessert',name:'Sweet Treat',category:'Desserts',price:180,description:'A little sweetness to end on a high note.',ingredients:'',diet:'',available:true,image:'https://images.unsplash.com/photo-1563805042-7684c019e1cb?auto=format&fit=crop&w=800&q=80'},
    {id:'cake',name:'Chocolate Cake',category:'Cakes',price:210,description:'A rich slice for an extra special moment.',ingredients:'',diet:'',available:true,image:'https://images.unsplash.com/photo-1578985545062-69928b1d9587?auto=format&fit=crop&w=800&q=80'},
    {id:'coffee',name:'Cafe Latte',category:'Coffee & Tea',price:160,description:'A smooth, comforting cup to slow down with.',ingredients:'',diet:'',available:true,image:'https://images.unsplash.com/photo-1541167760496-1628856ab772?auto=format&fit=crop&w=800&q=80'},
    {id:'shake',name:'Chocolate Shake',category:'Shakes & Beverages',price:190,description:'A chilled and creamy indulgence.',ingredients:'',diet:'',available:true,image:'https://images.unsplash.com/photo-1572490122747-3968b75cc699?auto=format&fit=crop&w=800&q=80'}
  ],
  gallery:[
    {label:'Pizza',image:'https://images.unsplash.com/photo-1513104890138-7c749659a591?auto=format&fit=crop&w=600&q=75'},
    {label:'Burgers',image:'https://images.unsplash.com/photo-1568901346375-23c9450c58cd?auto=format&fit=crop&w=600&q=75'},
    {label:'Pasta',image:'https://images.unsplash.com/photo-1473093295043-cdd812d0e601?auto=format&fit=crop&w=600&q=75'},
    {label:'Momos',image:'https://images.unsplash.com/photo-1563245372-f21724e3856d?auto=format&fit=crop&w=600&q=75'},
    {label:'Snacks',image:'https://images.unsplash.com/photo-1573080496219-bb080dd4f877?auto=format&fit=crop&w=600&q=75'},
    {label:'Desserts',image:'https://images.unsplash.com/photo-1563805042-7684c019e1cb?auto=format&fit=crop&w=600&q=75'},
    {label:'Cakes',image:'https://images.unsplash.com/photo-1578985545062-69928b1d9587?auto=format&fit=crop&w=600&q=75'},
    {label:'Shakes',image:'https://images.unsplash.com/photo-1572490122747-3968b75cc699?auto=format&fit=crop&w=600&q=75'},
    {label:'Cafe interior',image:'https://images.unsplash.com/photo-1445116572660-236099ec97a0?auto=format&fit=crop&w=600&q=75'},
    {label:'Dining together',image:'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=600&q=75'}
  ]
};
(function(){
'use strict';
const $=id=>document.getElementById(id), all=s=>Array.from(document.querySelectorAll(s));
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>CONFIG.currency+Number(n).toLocaleString('en-IN');
const validQty=n=>Number.isInteger(n)&&n>=1&&n<=20;
const safeUrl=s=>{try{const u=new URL(s);return u.protocol==='https:'?u.href:'';}catch(e){return '';}};
const fallback='data:image/svg+xml;charset=UTF-8,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 500"><rect width="600" height="500" fill="#173D2D"/><text x="300" y="245" text-anchor="middle" font-family="Georgia" font-size="48" fill="#F4B942">✳</text><text x="300" y="305" text-anchor="middle" font-family="sans-serif" font-size="22" fill="#FFF8EB">THE MANGO TREE CAFE</text></svg>');
function imgFallback(img){img.addEventListener('error',()=>{if(img.src!==fallback)img.src=fallback;},{once:true});}
all('img').forEach(imgFallback);all('[data-image]').forEach(img=>{const url=safeUrl(CONFIG.images[img.dataset.image]);if(url)img.src=url;});
const heroBg=document.querySelector('.hero-photo'),ambBg=document.querySelector('.ambience-photo');if(heroBg&&safeUrl(CONFIG.images.heroBackground))heroBg.style.backgroundImage='linear-gradient(90deg,rgba(13,38,28,.94),rgba(13,38,28,.82) 52%,rgba(13,38,28,.42)),url("'+safeUrl(CONFIG.images.heroBackground)+'")';if(ambBg&&safeUrl(CONFIG.images.ambience))ambBg.style.backgroundImage='url("'+safeUrl(CONFIG.images.ambience)+'")';
all('.ingredient').forEach((el,i)=>{let label=CONFIG.signatureLabels[i];if(label){el.querySelector('span').textContent=label.title;el.querySelector('small').textContent=label.detail;}});
$('year').textContent=new Date().getFullYear();
const header=$('header'),toggle=$('nav-toggle');function closeNav(){header.classList.remove('open');toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Open navigation');}toggle.addEventListener('click',()=>{let open=header.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Close navigation':'Open navigation');});all('.nav-links a').forEach(a=>a.addEventListener('click',closeNav));window.addEventListener('scroll',()=>header.classList.toggle('scrolled',window.scrollY>30),{passive:true});
let cart=[];try{let stored=JSON.parse(localStorage.getItem('mango-tree-cart-v1')||'[]');if(Array.isArray(stored))cart=stored.filter(x=>x&&CONFIG.products.some(p=>p.id===x.id&&p.available)&&validQty(x.qty));}catch(e){}
function saveCart(){try{localStorage.setItem('mango-tree-cart-v1',JSON.stringify(cart));}catch(e){}renderCart();}
function renderCart(){const target=$('cart-items');target.replaceChildren();$('cart-count').textContent=cart.reduce((a,x)=>a+x.qty,0);if(!cart.length)target.innerHTML='<p class="drawer-note">Your bag is empty. Explore the menu to find something delicious.</p>';let total=0;cart.forEach((item,i)=>{let p=CONFIG.products.find(x=>x.id===item.id);if(!p)return;total+=p.price*item.qty;let el=document.createElement('div');el.className='cart-item';el.innerHTML='<strong>'+esc(p.name)+'</strong><small>Demo price · '+money(p.price)+' each</small><div class="cart-row"><label>Qty <input type="number" min="1" max="20" value="'+item.qty+'" aria-label="Quantity for '+esc(p.name)+'"/></label><span>'+money(p.price*item.qty)+'</span><button type="button">Remove</button></div>';el.querySelector('input').addEventListener('change',e=>{let q=Number(e.target.value);if(validQty(q)){item.qty=q;saveCart();}else e.target.value=item.qty;});el.querySelector('button').addEventListener('click',()=>{cart.splice(i,1);saveCart();});target.appendChild(el);});$('cart-total').textContent=money(total);}
renderCart();
let activeDialog=null,lastFocus=null;function showDialog(id){if(activeDialog)closeDialog();lastFocus=document.activeElement;activeDialog=$(id);$('overlay').classList.remove('hidden');activeDialog.classList.remove('hidden');document.body.classList.add('locked');activeDialog.querySelector('button').focus();}function closeDialog(){if(!activeDialog)return;activeDialog.classList.add('hidden');$('overlay').classList.add('hidden');document.body.classList.remove('locked');activeDialog=null;if(lastFocus)lastFocus.focus();}
$('cart-open').addEventListener('click',()=>showDialog('cart-drawer'));$('cart-close').addEventListener('click',closeDialog);$('overlay').addEventListener('click',closeDialog);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeNav();closeDialog();}if(e.key==='Tab'&&activeDialog){const els=Array.from(activeDialog.querySelectorAll('button:not([disabled]),input:not([disabled]),a[href]'));if(!els.length)return;let first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
$('checkout').addEventListener('click',()=>{let msg=$('checkout-message');if(!cart.length){msg.textContent='Your bag is empty.';return;}if(!/^\d{8,15}$/.test(CONFIG.whatsapp)){msg.textContent='Demo only: ordering is not configured and no order was sent.';return;}let lines=cart.map(x=>{let p=CONFIG.products.find(p=>p.id===x.id);return p.name+' × '+x.qty+' — '+money(p.price*x.qty);});let total=cart.reduce((sum,x)=>sum+CONFIG.products.find(p=>p.id===x.id).price*x.qty,0);let text='Hello The Mango Tree Cafe! I would like to enquire about:\n'+lines.join('\n')+'\nDemo subtotal: '+money(total)+'\nPlease confirm availability and current prices.';window.open('https://wa.me/'+CONFIG.whatsapp+'?text='+encodeURIComponent(text),'_blank','noopener,noreferrer');msg.textContent='WhatsApp opened. This is an enquiry, not an order confirmation.';});
if(!$('carousel'))return;
$('address').textContent=CONFIG.address||'Exact address not yet provided';$('hours').textContent=CONFIG.hours||'Opening hours not yet provided';$('contact-info').textContent=[CONFIG.phone,CONFIG.email].filter(Boolean).join(' · ')||'Contact details not yet provided';
[['instagram','Instagram'],['facebook','Facebook']].forEach(([key,label])=>{const url=safeUrl(CONFIG[key]);if(url){let a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.textContent=label+' ↗';$('social-links').appendChild(a);}});
if(safeUrl(CONFIG.mapsUrl)){all('a[href^="https://www.google.com/maps/search/"]').forEach(a=>a.href=safeUrl(CONFIG.mapsUrl));}
let category='All',active=0,visible=[];
function showDetails(p){location.hash='dish/'+encodeURIComponent(p.id);}
function drawFilters(){const el=$('filters');el.replaceChildren();['All',...CONFIG.categories].forEach(cat=>{let b=document.createElement('button');b.type='button';b.className='filter'+(cat===category?' active':'');b.textContent=cat;b.setAttribute('aria-pressed',String(cat===category));b.addEventListener('click',()=>{category=cat;active=0;drawFilters();drawCards();});el.appendChild(b);});}
function markActive(){const cards=Array.from($('carousel').children);cards.forEach((c,i)=>c.classList.toggle('active',i===active));$('menu-status').textContent=visible.length?'Dish '+(active+1)+' of '+visible.length+' · '+visible[active].name:'No demo dishes in this category yet.';}
function drawCards(){const el=$('carousel');el.replaceChildren();visible=CONFIG.products.filter(p=>category==='All'||p.category===category);visible.forEach((p,i)=>{let card=document.createElement('article');card.className='food-card';card.innerHTML='<img loading="lazy" src="'+esc(safeUrl(p.image)||fallback)+'" alt="Illustrative '+esc(p.name)+'"/><div class="food-card-content"><span class="card-category">'+esc(p.category)+' · DEMO</span><h3>'+esc(p.name)+'</h3><p>'+esc(p.description)+'</p><span class="card-price">'+money(p.price)+'</span><span class="availability">'+(p.available?'Sample · availability unconfirmed':'Unavailable')+'</span><div class="card-actions"><button type="button">View details</button><button type="button" '+(p.available?'':'disabled="disabled"')+'>Order</button></div></div>';imgFallback(card.querySelector('img'));card.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>showDetails(p)));card.addEventListener('focusin',()=>{active=i;markActive();});el.appendChild(card);});el.scrollLeft=0;markActive();}
function moveTo(i){if(!visible.length)return;active=Math.max(0,Math.min(i,visible.length-1));const card=$('carousel').children[active];const target=card.offsetLeft-$('carousel').offsetLeft-(window.innerWidth>600?($('carousel').clientWidth-card.clientWidth)/2:0);$('carousel').scrollTo({left:target,behavior:reduce.matches?'auto':'smooth'});markActive();}
$('prev').addEventListener('click',()=>moveTo(active-1));$('next').addEventListener('click',()=>moveTo(active+1));$('carousel').addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();moveTo(active+1);}if(e.key==='ArrowLeft'){e.preventDefault();moveTo(active-1);}});let scrollTimer;$('carousel').addEventListener('scroll',()=>{clearTimeout(scrollTimer);scrollTimer=setTimeout(()=>{let c=$('carousel'),cards=Array.from(c.children);if(!cards.length)return;let center=c.getBoundingClientRect().left+(window.innerWidth>600?c.clientWidth/2:0);let best=0,dist=Infinity;cards.forEach((card,i)=>{let rect=card.getBoundingClientRect(),position=window.innerWidth>600?rect.left+rect.width/2:rect.left;let d=Math.abs(position-center);if(d<dist){dist=d;best=i;}});active=best;markActive();},80);},{passive:true});drawFilters();drawCards();
CONFIG.gallery.forEach(item=>{let figure=document.createElement('figure');let img=document.createElement('img');img.loading='lazy';img.src=safeUrl(item.image)||fallback;img.alt='Illustrative '+item.label;imgFallback(img);let cap=document.createElement('figcaption');cap.textContent=item.label;figure.append(img,cap);$('gallery-grid').appendChild(figure);});
/* Scroll-linked layered-image animation. No 3D model is implied or required.
   One RAF loop handles all scenes; transforms are reversible and scrolling is never pinned. */
const reduce=window.matchMedia('(prefers-reduced-motion: reduce)');let ticking=false;
function clamp(n,min,max){return Math.max(min,Math.min(max,n));}
function progress(el){const r=el.getBoundingClientRect();return clamp((innerHeight-r.top)/(innerHeight+r.height),0,1);}
function animateScroll(){ticking=false;header.classList.toggle('scrolled',window.scrollY>30);if(reduce.matches)return;let hero=$('home'),hp=clamp(-hero.getBoundingClientRect().top/Math.max(hero.offsetHeight,1),0,1);document.querySelector('.hero-art-frame').style.transform='translate3d('+(-hp*65)+'px,'+(hp*90)+'px,0) scale('+(1-hp*.12)+') rotate('+(-hp*6)+'deg)';document.querySelector('.hero-photo').style.transform='translate3d(0,'+(hp*70)+'px,0) scale(1.08)';let scene=document.querySelector('.story-visual'),sp=progress(scene),main=scene.querySelector('.story-img-main'),small=scene.querySelector('.story-img-small');main.style.transform='translate3d(0,'+((.5-sp)*90)+'px,0) rotate('+((.5-sp)*3)+'deg)';small.style.transform='translate3d(0,'+((sp-.5)*110)+'px,0) rotate('+((sp-.5)*6)+'deg)';let sig=document.querySelector('.signature-scene'),p=progress(sig),image=sig.querySelector('img'),scale=0.78+Math.sin(Math.PI*p)*.27;image.style.transform='translate3d('+((.5-p)*100)+'px,'+((.5-p)*45)+'px,0) scale('+scale+') rotate('+((p-.5)*10)+'deg)';sig.querySelectorAll('.ingredient').forEach((el,i)=>{let start=.23+i*.09;el.style.opacity=String(clamp((p-start)/.12,0,1)*clamp((.85-p)/.12,0,1));el.style.transform='translateY('+((1-clamp((p-start)/.12,0,1))*15)+'px)';});let amb=document.querySelector('.ambience'),ap=progress(amb);document.querySelector('.ambience-photo').style.transform='scale(1.12) translateY('+((.5-ap)*55)+'px)';}
function requestAnimation(){if(!ticking){ticking=true;requestAnimationFrame(animateScroll);}}
window.addEventListener('scroll',requestAnimation,{passive:true});window.addEventListener('resize',requestAnimation,{passive:true});requestAnimation();
if(!reduce.matches&&Element.prototype.animate){all('.hero-animate').forEach((el,i)=>el.animate([{opacity:0,transform:'translateY(32px) scale(.97)'},{opacity:1,transform:'translateY(0) scale(1)'}],{duration:850,delay:120+i*140,easing:'cubic-bezier(.2,.7,.2,1)',fill:'both'}));if('IntersectionObserver'in window){let observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.animate([{opacity:0,transform:'translateY(35px)'},{opacity:1,transform:'translateY(0)'}],{duration:750,easing:'ease-out',fill:'both'});observer.unobserve(entry.target);}}),{threshold:.12});all('.reveal,.gallery-grid figure').forEach(el=>observer.observe(el));}}
reduce.addEventListener&&reduce.addEventListener('change',()=>{if(reduce.matches){all('.hero-art-frame,.hero-photo,.story-img-main,.story-img-small,.signature-scene img,.ingredient,.ambience-photo').forEach(el=>{el.style.transform='';el.style.opacity='';});}requestAnimation();});
/* Hash-based pages work on Blogger's home route without requiring a server or build. */
let fullCategory='All',currentDish=null;
function openWhatsApp(text,status){if(!/^\d{8,15}$/.test(CONFIG.whatsapp)){status.textContent='WhatsApp ordering is not configured yet. Please check back later.';return;}status.textContent='Opening WhatsApp. Your enquiry is not an order confirmation.';window.open('https://wa.me/'+CONFIG.whatsapp+'?text='+encodeURIComponent(text),'_blank','noopener,noreferrer');}
$('hero-whatsapp').addEventListener('click',()=>openWhatsApp('Hello! I would like to ask about the menu at The Mango Tree Cafe.', $('hero-whatsapp-status')));
$('menu-whatsapp').addEventListener('click',()=>openWhatsApp('Hello! I would like to ask about the menu at The Mango Tree Cafe.', $('menu-whatsapp-status')));
function drawFullFilters(){let el=$('full-filters');el.replaceChildren();['All',...CONFIG.categories].forEach(cat=>{let b=document.createElement('button');b.type='button';b.className='filter'+(cat===fullCategory?' active':'');b.textContent=cat;b.setAttribute('aria-pressed',String(cat===fullCategory));b.addEventListener('click',()=>{fullCategory=cat;drawFullFilters();drawFullGrid();});el.appendChild(b);});}
function drawFullGrid(){let term=$('full-search').value.trim().toLowerCase(),grid=$('full-grid');grid.replaceChildren();let items=CONFIG.products.filter(p=>(fullCategory==='All'||p.category===fullCategory)&&(p.name+' '+p.category+' '+p.description).toLowerCase().includes(term));items.forEach(p=>{let card=document.createElement('article');card.className='food-card';card.innerHTML='<img loading="lazy" src="'+esc(safeUrl(p.image)||fallback)+'" alt="Illustrative '+esc(p.name)+'"/><div class="food-card-content"><span class="card-category">'+esc(p.category)+' · SAMPLE</span><h3>'+esc(p.name)+'</h3><p>'+esc(p.description)+'</p><span class="card-price">'+money(p.price)+' <small>demo</small></span><span class="availability">'+(p.available?'Availability unconfirmed':'Unavailable in sample data')+'</span><div class="card-actions"><button type="button">View details &amp; order ↗</button></div></div>';imgFallback(card.querySelector('img'));card.querySelector('button').addEventListener('click',()=>showDetails(p));grid.appendChild(card);});$('full-status').textContent=items.length?items.length+' sample dish'+(items.length===1?'':'es')+' · Prices and availability are not confirmed.':'No sample dishes match your search.';}
$('full-search').addEventListener('input',drawFullGrid);drawFullFilters();drawFullGrid();
function drawDish(p){currentDish=p;$('dish-image').src=safeUrl(p.image)||fallback;$('dish-image').alt='Illustrative '+p.name;$('dish-category').textContent=p.category+' · SAMPLE DISH';$('dish-name').textContent=p.name;$('dish-price').textContent=money(p.price)+' · demo price';$('dish-description').textContent=p.description;$('dish-ingredients').textContent=p.ingredients?'Ingredients: '+p.ingredients:'Ingredients not yet provided.';$('dish-diet').textContent=p.diet?'Dietary information: '+p.diet:'Vegetarian / non-vegetarian status not yet verified.';$('dish-availability').textContent=p.available?'Availability and dietary information are not yet confirmed.':'Unavailable in sample data.';$('dish-qty').value=1;$('dish-notes').value='';$('dish-status').textContent='';$('dish-whatsapp').disabled=!p.available;$('dish-add-cart').disabled=!p.available;let other=CONFIG.products.filter(x=>x.id!==p.id);other.sort((a,b)=>(b.category===p.category)-(a.category===p.category));let grid=$('related-grid');grid.replaceChildren();other.slice(0,4).forEach(x=>{let card=document.createElement('article');card.className='related-card';let img=document.createElement('img');img.src=safeUrl(x.image)||fallback;img.alt='Illustrative '+x.name;img.loading='lazy';imgFallback(img);let a=document.createElement('a');a.href='#dish/'+encodeURIComponent(x.id);a.textContent=x.name+' · '+money(x.price)+' demo';card.append(img,a);grid.appendChild(card);});}
imgFallback($('dish-image'));
$('dish-whatsapp').addEventListener('click',()=>{let qty=Number($('dish-qty').value);if(!currentDish||!validQty(qty)){$('dish-status').textContent='Please choose a quantity between 1 and 20.';return;}let notes=$('dish-notes').value.trim();let text='Hello The Mango Tree Cafe! I would like to enquire about '+currentDish.name+' × '+qty+'.'+(notes?'\nSpecial request: '+notes:'')+'\nPlease confirm the ingredients, availability and current price.';openWhatsApp(text,$('dish-status'));});
$('dish-add-cart').addEventListener('click',()=>{let qty=Number($('dish-qty').value);if(!currentDish||!validQty(qty)){$('dish-status').textContent='Please choose a quantity between 1 and 20.';return;}let existing=cart.find(x=>x.id===currentDish.id);if(existing&&existing.qty+qty>20){$('dish-status').textContent='Maximum 20 of each dish in the bag.';return;}if(existing)existing.qty+=qty;else cart.push({id:currentDish.id,qty:qty});saveCart();$('dish-status').textContent='Added to your demo bag. Special requests can be sent using WhatsApp.';});
let previousView='home';
function route(){let hash=location.hash.slice(1),isMenu=hash==='full-menu',isDish=hash.startsWith('dish/'),p=null;if(isDish){try{p=CONFIG.products.find(x=>x.id===decodeURIComponent(hash.slice(5)));}catch(e){}if(!p){isDish=false;isMenu=true;}}let view=isDish?'dish':isMenu?'menu':'home';$('home-content').classList.toggle('hidden',view!=='home');$('full-menu-page').classList.toggle('hidden',view!=='menu');$('dish-page').classList.toggle('hidden',view!=='dish');document.body.classList.toggle('inner-view',view!=='home');if(isDish)drawDish(p);closeNav();if(view!=='home'){window.scrollTo({top:0,behavior:'auto'});let heading=$(view==='dish'?'dish-name':'full-menu-title');heading.setAttribute('tabindex','-1');heading.focus({preventScroll:true});}else if(previousView!=='home'&&hash){let target=document.getElementById(hash);if(target)requestAnimationFrame(()=>target.scrollIntoView({behavior:'auto'}));}previousView=view;}
window.addEventListener('hashchange',route);route();

})();
